// Custom Cloudflare Worker entrypoint wrapping OpenNext.
// Conforms to the Workers ExportedHandler contract: { fetch, scheduled }.
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import openNextHandler from "../.open-next/worker.js";

// Re-export Durable Objects required by OpenNext for queue & caching.
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "../.open-next/worker.js";

import { deliverPortalAlerts } from "../src/lib/portal-push";
import { runJobBatch } from "../src/lib/background-jobs";

export interface ScheduledController {
  readonly scheduledTime: number;
  readonly cron: string;
  noRetry(): void;
}

export interface ExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}

export interface CloudflareEnv {
  ASSETS?: { fetch: typeof fetch };
  DATABASE_URL?: string;
  DIRECT_URL?: string;
  JWT_SECRET?: string;
  SETUP_SECRET?: string;
  NEXT_PUBLIC_VAPID_PUBLIC_KEY?: string;
  VAPID_PRIVATE_KEY?: string;
  VAPID_SUBJECT?: string;
  [key: string]: unknown;
}

const SECRET_KEYS = [
  "DATABASE_URL",
  "DIRECT_URL",
  "JWT_SECRET",
  "SETUP_SECRET",
  "NEXT_PUBLIC_VAPID_PUBLIC_KEY",
  "VAPID_PRIVATE_KEY",
  "VAPID_SUBJECT",
] as const;

/** Cloudflare bindings are not automatically present on process.env in every runtime. */
function bridgeSecrets(env: CloudflareEnv): void {
  for (const key of SECRET_KEYS) {
    const value = env[key];
    if (typeof value === "string" && value.length > 0) {
      process.env[key] = value;
    }
  }
}

async function runScheduledJobs(): Promise<void> {
  // Lease is 3x the cron interval so a slow batch cannot overlap the next cron.
  const summary = await runJobBatch("cron-worker", 10, 15);
  console.log(
    `[Cron Trigger] claimed=${summary.claimed} completed=${summary.completed} ` +
      `retried=${summary.retried} failed=${summary.failed} ` +
      `ownershipLost=${summary.ownershipLost} postProcessErrors=${summary.postProcessErrors}`
  );
  if (summary.postProcessErrors > 0) {
    throw new Error(`${summary.postProcessErrors} job(s) failed after processing`);
  }
}

const worker = {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext) {
    bridgeSecrets(env);
    return openNextHandler.fetch(request, env, ctx);
  },

  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    bridgeSecrets(env);
    console.log(
      `[Cron Trigger] Fired at ${new Date(controller.scheduledTime).toISOString()} ` +
        `with pattern "${controller.cron}"`
    );
    ctx.waitUntil(Promise.all([runScheduledJobs(), deliverPortalAlerts()]));
  },
};

export default worker;
